/**
 * Which PvP trinket a unit's slots hold. Its own module so that the kill-tier
 * files can ask without importing `ccTrinketAnalysis`, which imports them.
 */
import { type ICombatUnit, LogEvent } from "@gladlog/parser-compat";

import trinketItemIdsData from "../data/trinketItemIds.json";
import {
  ADAPTATION_TRIGGER_AURA_ID,
  MEDALLION_SPELL_ID,
} from "./pvpTrinketUses";
import { roundEndMs } from "./roundEnd";

/** Item IDs for Relentless (passive DR, no active) — generated by start:generateTrinketItemIds */
const RELENTLESS_ITEM_IDS = new Set<string>(
  trinketItemIdsData.relentlessItemIds,
);
/** Item IDs for Adaptation (auto-break on 5s CC, no manual cast) — generated by start:generateTrinketItemIds */
const ADAPTATION_ITEM_IDS = new Set<string>(
  trinketItemIdsData.adaptationItemIds,
);
/** Item IDs whose on-use is Gladiator's Medallion (ItemEffect.SpellID 336126),
 * generated by the same script. Reliability round 3 W1j: every trinket that was
 * not Adaptation / Relentless used to count as a Medallion, so a player with
 * two non-PvP trinkets was "PvP Trinket available" (0e0663e6). On a 303-file
 * sample every one of 2,719 Medallion casters held one of these items; 79 of
 * 3,831 players the old rule called "Gladiator" held none and never cast. */
const GLADIATOR_ITEM_IDS = new Set<string>(trinketItemIdsData.gladiatorItemIds);

/** "None" = equipment is known and holds no PvP trinket (no Medallion item and
 * no Medallion cast); "Unknown" = no equipment to read. */
export type TrinketType =
  "Gladiator" | "Adaptation" | "Relentless" | "None" | "Unknown";

export function detectTrinketType(unit: ICombatUnit): TrinketType {
  const trinketSlots = (unit.info?.equipment ?? []).filter((_, i) =>
    [12, 13].includes(i),
  );
  if (trinketSlots.some((e) => RELENTLESS_ITEM_IDS.has(e.id)))
    return "Relentless";
  if (trinketSlots.some((e) => ADAPTATION_ITEM_IDS.has(e.id)))
    return "Adaptation";
  if (
    trinketSlots.some((e) => GLADIATOR_ITEM_IDS.has(e.id)) ||
    (unit.spellCastEvents ?? []).some((e) => e.spellId === MEDALLION_SPELL_ID)
  )
    return "Gladiator";
  if (trinketSlots.length > 0) return "None";
  // no trinket slot to read: Adaptation's own trigger aura on the unit is the
  // log's proof of it, as a Medallion press is of the Medallion (codex
  // 85-tk-L5-T278-1 #4: read "Unknown", the [HEALER EXPOSURE] line priced a
  // wiped lockout as a pressable trinket "back 4:00" past a 3:24 round end)
  if (
    (unit.auraEvents ?? []).some(
      (a) =>
        a.spellId === ADAPTATION_TRIGGER_AURA_ID &&
        a.logLine.event === LogEvent.SPELL_AURA_APPLIED &&
        (a.destUnitId === undefined || a.destUnitId === unit.id),
    )
  )
    return "Adaptation";
  return "Unknown";
}

/**
 * Does the unit hold a PvP trinket it can press, read off the unit alone
 * (`pvpTrinketRemainingSecondsAt` is null for Relentless / None, and keeps
 * Adaptation's own break-ready seconds — another fact): Relentless is
 * passive, "None" holds two other trinkets (user ruling 2026-10-31, fact7 r5:
 * 705 of 17,232 `trinket up` lines on the 605, 36 units, 247 with no break
 * racial seen). The kill tier still treats such a unit as `locked` — P-b7's
 * tier is not this fact — and only what the line says changes.
 *
 * Pipeline T126 (fact13 D34, 78ae1848 r0): Adaptation is passive too — it
 * breaks a control of 5 s or more by itself (aura 336135, trigger 283167),
 * and there is nothing to press; the round's Chaos Nova of 4.0 s could not
 * trip it, yet both attempts on its holder printed `trinket up`. A logged
 * Gladiator's Medallion press inside the round still proves a trinket to
 * press whatever the slots say (a stale item list); a Medallion counts by its
 * item in the slots, else by such a press.
 */
export function hasPressablePvpTrinket(
  unit: ICombatUnit,
  /** the round the reading is for (`medallionPressedInRound`) */
  round: PvpTrinketRound,
): boolean {
  const slots = (unit.info?.equipment ?? []).filter((_, i) =>
    [12, 13].includes(i),
  );
  // a Medallion in the slots (codex 85-tk-M-T126-1b #2: not a Medallion
  // cast at any time — `detectTrinketType` reads one, unbounded)
  if (
    detectTrinketType(unit) === "Gladiator" &&
    slots.some((e) => GLADIATOR_ITEM_IDS.has(e.id))
  )
    return true;
  if (slots.length === 0) return true; // no equipment to read
  return medallionPressedInRound(unit, round);
}

/** The round a trinket reading is for: the shape `roundEndMs` reads. */
export type PvpTrinketRound = Parameters<typeof roundEndMs>[0] & {
  startTime: number;
};

/** Did the unit press Gladiator's Medallion inside the round — from its start
 * to `roundEndMs` (a Solo Shuffle unit's casts run on past the deciding
 * death; codex 85-tk-M-T126-1)? The one bound for `hasPressablePvpTrinket`'s
 * override and for the gate that excludes such a unit (scan5/t126). */
export function medallionPressedInRound(
  unit: ICombatUnit,
  round: PvpTrinketRound,
): boolean {
  const endMs = roundEndMs(round);
  return (unit.spellCastEvents ?? []).some(
    (e) =>
      e.spellId === MEDALLION_SPELL_ID &&
      e.logLine.timestamp >= round.startTime &&
      e.logLine.timestamp <= endMs,
  );
}

/** Gladiator's Badge on-use spell (`trinketItemIds.json`). */
export const GLADIATOR_BADGE_SPELL_ID =
  trinketItemIdsData.gladiatorBadgeSpellId;
/** Item IDs whose on-use is Gladiator's Badge (ItemEffect.SpellID 345228). */
const BADGE_ITEM_IDS = new Set<string>(trinketItemIdsData.badgeItemIds);

/**
 * How many Gladiator's Badges the unit wears (trinket slots 12 / 13; 0 when
 * the equipment is unknown). GH #176: two badges are two items with a
 * cooldown each — 605 files: 787 one-badge players, 876 recast gaps, none
 * under 59 s; 6 two-badge players, 19 gaps, all of them 26.7–49.7 s.
 */
export function equippedBadgeCount(unit: ICombatUnit): number {
  return (unit.info?.equipment ?? []).filter(
    (e, i) => [12, 13].includes(i) && BADGE_ITEM_IDS.has(e.id),
  ).length;
}
